// بيانات الخطوط العربية الإضافية لـ Esharq — المقطع العربيّ فقط، مضمّن base64 (woff2).
// المصدر: Google Fonts (رخصة SIL OFL) عدا خطّ Saudi (ملفات الويب الرسمية المنشورة).
// الخطوط المتغيّرة (Cairo/Changa/El Messiri) ملفٌّ واحد يغطّي كلّ مدى الوزن، فيُعلَن
// مداه في واصف font-weight بدل تكرار الملف لكلّ وزن — أصغر حجماً وأدقّ استيفاءً.
// تُولَّد آلياً؛ لا تُحرَّر يدوياً.

export interface EsharqFontFace {
    /** واصف font-weight: قيمة واحدة ("400") أو مدى خطّ متغيّر ("200 1000"). */
    weight: string;
    /** ملفّ woff2 مضمّن base64. */
    b64: string;
}

export interface EsharqFontData {
    /** اسم العائلة الحقيقي (للعرض والتشخيص فقط — الحقن يُعيد تعريف خطوط ديسكورد). */
    family: string;
    faces: EsharqFontFace[];
}

export const EXTRA_FONTS: Record<string, EsharqFontData> = {
    // Cairo — خطّ عصري واسع الانتشار
    cairo: {
        family: "Cairo",
        faces: [
            { weight: "200 1000", b64: "" }
        ]
    },
    // Almarai — خطّ خليجي نظيف عالي الوضوح
    almarai: {
        family: "Almarai",
        faces: [
            { weight: "400", b64: "" },
            { weight: "700", b64: "" }
        ]
    },
    // Changa — خطّ عناوين عربي مميّز
    changa: {
        family: "Changa",
        faces: [
            { weight: "200 800", b64: "" }
        ]
    },
    // El Messiri — خطّ أنيق بلمسة كلاسيكية
    elMessiri: {
        family: "El Messiri",
        faces: [
            { weight: "400 700", b64: "" }
        ]
    },
    // Saudi — الخطّ السعودي الرسمي
    saudi: {
        family: "Saudi",
        faces: [
            { weight: "400", b64: "" },
            { weight: "700", b64: "" }
        ]
    }
};
